def check(path):
    """The cheap checks first: complete? an expected sender? a version we know?"""
    with open(path, "rb") as f:
        f.seek(max(0, path.stat().st_size - 64))           # only the last bytes
        if b"</FundsXML4>" not in f.read():
            raise Rejected("INCOMPLETE", "no closing </FundsXML4>")
    ctl = read_control_data(path)                         # only the first lines
    if ctl["data_supplier"] not in SENDERS:
        raise Rejected("UNKNOWN_SENDER", ...)
    if not ctl["version"].startswith("4."):
        raise Rejected("UNSUPPORTED_VERSION", ...)
    return ctl

def emt(self, r):
    self.template(r, "EMT", "V4.2", r.findtext("GeneralInformation/Code"), ...,
        ongoing_costs=r.findtext("CostsAndChargesExAnte/Fund/OngoingCosts"))

def eet(self, r):
    self.template(r, "EET", "V1.1.3", ...,
        sfdr_product_type=r.findtext("MainCriterias/SFDRProductType"))

def tpt(self, r):
    self.template(r, "TPT", r.findtext("TPTVersion"), r.findtext("PortfolioID/Code"), ...,
        tpt_positions=len(r.findall("Positions/Position")))
